import {CLASSES,configSection,outstanding,paidFor,ledgerBalance,today,round} from '../core/business.js?v=20261102-v6b';
export function install(ctx){
 const b=()=>ctx.business||{};let selectedTab='income';
 const accountsOptions=()=>b().accounts.filter(a=>a.active).map(a=>`<option value="${a.id}">${ctx.esc(a.name)}</option>`).join('');
 const groupOptions=selected=>Object.entries(CLASSES).map(([key,label])=>`<option value="${key}" ${selected===key?'selected':''}>${label}</option>`).join('');
 const categoryInput=(value='')=>`<label class="field">Categoria<input name="category" list="category-options" value="${ctx.esc(value)}" required maxlength="150"><datalist id="category-options">${configSection(ctx.settings,'finance').categories.map(c=>`<option>${ctx.esc(c)}</option>`).join('')}</datalist></label>`;
 function financePage(){const entries=b().entries||[],settlements=b().settlements||[],accounts=b().accounts||[];const receive=entries.filter(e=>e.kind==='income').reduce((n,e)=>n+outstanding(e,settlements),0),pay=entries.filter(e=>e.kind==='expense').reduce((n,e)=>n+outstanding(e,settlements),0);ctx.shell(`${ctx.head('Seu financeiro, por inteiro.','Contas a receber, contas a pagar, compras e movimentações dos sócios.')}<section class="metrics three">${ctx.metric('Saldo realizado',ctx.money(accounts.reduce((n,a)=>n+ledgerBalance(a,entries,settlements,today()),0)),'Saldos de abertura + baixas','bank')}${ctx.metric('A receber',ctx.money(receive),'Saldo pendente de recebimento','finance','positive')}${ctx.metric('A pagar',ctx.money(pay),'Saldo pendente de pagamento','finance','negative')}</section><div class="tabs" role="tablist">${[['income','A receber'],['expense','A pagar'],['purchases','Compras'],['partners','Sócios e pró-labore'],['recurring','Despesas fixas'],['audit','Histórico']].map(([k,l])=>`<button role="tab" aria-selected="${k===selectedTab}" data-fin-tab="${k}" class="${selectedTab===k?'active':''}">${l}</button>`).join('')}</div><div class="toolbar"><input type="search" id="finance-search" aria-label="Buscar lançamento" placeholder="Buscar descrição, cliente ou categoria…"><select id="finance-status" aria-label="Situação dos lançamentos"><option value="open">Em aberto</option><option value="all">Todos</option><option value="overdue">Vencidos</option><option value="paid">Liquidados</option><option value="void">Cancelados</option></select><button class="secondary small" id="transfer" ${!ctx.can('finance','settle')?'hidden':''}>Transferir entre contas</button><button class="primary small" id="new-entry" ${!ctx.can('finance','create')?'hidden':''}>${ctx.icon('plus')} Novo lançamento</button></div><div id="finance-content"></div>`);
  document.querySelectorAll('[data-fin-tab]').forEach(el=>el.onclick=()=>{selectedTab=el.dataset.finTab;financePage()});ctx.$('#new-entry').onclick=()=>selectedTab==='recurring'?recurringDialog():entryDialog();ctx.$('#transfer').onclick=transferDialog;
  function draw(){if(selectedTab==='recurring'){drawRecurring();return}if(selectedTab==='audit'){drawAudit();return}const search=ctx.$('#finance-search').value.toLowerCase(),status=ctx.$('#finance-status').value;const rows=entries.filter(e=>{const pending=outstanding(e,settlements),group=selectedTab==='purchases'?e.kind==='expense'&&['cost','asset'].includes(e.class):selectedTab==='partners'?e.class==='equity'||e.category==='Pró-labore':e.kind===selectedTab;return group&&(e.description+' '+e.party+' '+e.category).toLowerCase().includes(search)&&(status==='all'||status==='void'&&e.voided||!e.voided&&(status==='open'&&pending>0||status==='paid'&&pending===0||status==='overdue'&&pending>0&&e.due_date<today()))});
   ctx.$('#finance-content').innerHTML=`<section class="panel">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Lançamento</th><th>Categoria</th><th>Vencimento</th><th>Total</th><th>Baixado</th><th>Saldo</th><th>Situação</th><th></th></tr></thead><tbody>${rows.map(e=>{const pending=outstanding(e,settlements);return `<tr><td><strong>${ctx.esc(e.description)}</strong><small>${ctx.esc(e.party||'—')}</small></td><td>${ctx.esc(e.category)}<small>${CLASSES[e.class]}</small></td><td class="${pending&&e.due_date<today()?'overdue':''}">${ctx.date(e.due_date)}</td><td class="nowrap">${ctx.money(e.amount)}</td><td>${ctx.money(paidFor(e,settlements))}</td><td>${ctx.money(pending)}</td><td><span class="badge ${e.voided?'danger-badge':pending===0?'success':e.due_date<today()?'warning':''}">${e.voided?'Cancelado':pending===0?'Liquidado':paidFor(e,settlements)>0?'Parcial':e.due_date<today()?'Vencido':'Em aberto'}</span></td><td class="nowrap"><button class="secondary small" data-entry="${e.id}">Detalhes</button>${pending&&ctx.can('finance','settle')?` <button class="primary small" data-settle="${e.id}">${e.kind==='income'?'Receber':'Pagar'}</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:ctx.empty('Nenhum lançamento neste filtro.','Cadastre uma conta ou gere as parcelas de um pedido.')}</section>`;document.querySelectorAll('[data-entry]').forEach(el=>el.onclick=()=>entryDetails(el.dataset.entry));document.querySelectorAll('[data-settle]').forEach(el=>el.onclick=()=>settlementDialog(el.dataset.settle));
  }draw();ctx.$('#finance-search').oninput=draw;ctx.$('#finance-status').onchange=draw;
 }
 function entryDialog(entry=null){const kind=entry?.kind||(selectedTab==='income'?'income':'expense'),group=entry?.class||(selectedTab==='purchases'?'cost':selectedTab==='partners'?'equity':kind==='income'?'revenue':'expense');const d=ctx.modal(entry?'Editar lançamento':'Novo lançamento financeiro',`<form id="entry-form"><div class="grid2"><label class="field">Tipo<select name="kind"><option value="income" ${kind==='income'?'selected':''}>A receber / entrada</option><option value="expense" ${kind==='expense'?'selected':''}>A pagar / saída</option></select></label><label class="field">Classificação gerencial<select name="class">${groupOptions(group)}</select></label>${ctx.field('Descrição','description','text',entry?.description||'','required minlength="2" maxlength="1000"')}${ctx.field('Cliente, fornecedor ou sócio','party','text',entry?.party||'','maxlength="200" list="partners-options"')}<datalist id="partners-options">${configSection(ctx.settings,'finance').partners.map(p=>`<option>${ctx.esc(p)}</option>`).join('')}</datalist>${categoryInput(entry?.category||(selectedTab==='purchases'?'Matéria-prima':selectedTab==='partners'?'Distribuição de lucros':kind==='income'?'Vendas':'Outros'))}${ctx.field('Valor total (R$)','amount','number',entry?.amount||'','required min="0.01" max="9999999999" step="0.01"')}${ctx.field('Vencimento','due_date','date',entry?.due_date||today(),'required')}${ctx.field('Competência','competence','date',entry?.competence||today(),'required')}</div><div class="note">Pró-labore é despesa operacional. Aportes e distribuições de lucro são movimentações de capital e não entram como venda ou despesa da DRE. O lançamento só altera o caixa quando uma baixa é registrada.</div><p id="entry-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Salvar lançamento</button></div></form>`,{wide:true});d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();ev.submitter.disabled=true;const v=Object.fromEntries(new FormData(ev.target));try{await ctx.rpc('save_fin_entry',{p_id:entry?.id||null,p_kind:v.kind,p_class:v.class,p_category:v.category,p_description:v.description,p_party:v.party,p_amount:Number(v.amount),p_due:v.due_date,p_competence:v.competence});await ctx.load();d.close();ctx.render('finance');ctx.toast('Lançamento salvo.')}catch(e){d.querySelector('#entry-error').textContent=e.message;ev.submitter.disabled=false}}}
 function settlementDialog(id){const e=b().entries.find(e=>e.id===id);if(!e)return;if(!b().accounts.some(a=>a.active)){ctx.toast('Cadastre uma conta em Configurações → Financeiro antes de registrar a baixa.');return}const request=crypto.randomUUID(),remaining=outstanding(e,b().settlements);const d=ctx.modal(e.kind==='income'?'Registrar recebimento':'Registrar pagamento',`<p class="muted">${ctx.esc(e.description)} · Saldo ${ctx.money(remaining)}</p><form><label class="field">Conta de movimentação<select name="account" required>${accountsOptions()}</select></label>${ctx.field('Valor da baixa (R$)','amount','number',remaining,'required min="0.01" max="'+remaining+'" step="0.01"')}${ctx.field('Data da movimentação','date','date',today(),'required')}<label class="field">Forma de pagamento<select name="payment_method">${configSection(ctx.settings,'finance').payment_methods.map(m=>`<option>${ctx.esc(m)}</option>`).join('')}</select></label>${ctx.field('Observação','memo','text','','maxlength="500"')}<p class="note">Este comando registra uma movimentação já realizada. Ele não transfere dinheiro nem realiza pagamentos no banco.</p><p class="form-error" role="alert"></p><div class="form-actions"><button class="secondary" type="button" data-close>Cancelar</button><button class="primary" type="submit">Confirmar registro</button></div></form>`);d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();ev.submitter.disabled=true;const v=Object.fromEntries(new FormData(ev.target));try{await ctx.rpc('settle_entry',{p_entry:e.id,p_account:v.account,p_amount:Number(v.amount),p_date:v.date,p_memo:(v.payment_method||'')+' · '+(v.memo||''),p_request:request});await ctx.load();d.close();ctx.render(ctx.current);ctx.toast('Baixa registrada sem duplicar o título.')}catch(err){d.querySelector('.form-error').textContent=err.message;ev.submitter.disabled=false}}}
 function entryDetails(id){const e=b().entries.find(e=>e.id===id);if(!e)return;const payments=b().settlements.filter(s=>s.entry_id===e.id);const d=ctx.modal('Detalhes do lançamento',`<div class="order-detail-top"><div><h3>${ctx.esc(e.description)}</h3><p>${ctx.esc(e.party||e.category)}</p></div><div><strong>${ctx.money(e.amount)}</strong><small>Saldo ${ctx.money(outstanding(e,b().settlements))}</small></div></div><p class="muted">Vencimento ${ctx.date(e.due_date)} · Competência ${ctx.date(e.competence)}</p>${e.voided?'<p class="error">Cancelado: '+ctx.esc(e.void_reason)+'</p>':''}<div class="form-actions">${e.voided&&!e.transfer_group&&ctx.can('finance','edit')?'<button class="secondary" id="details-restore">Reativar título</button>':''}${!e.voided&&outstanding(e,b().settlements)>0&&ctx.can('finance','settle')?'<button class="primary" id="details-settle">Registrar baixa</button>':''}${!e.quote_id&&!payments.some(s=>!s.reversed)&&!e.voided&&ctx.can('finance','edit')?'<button class="secondary" id="details-edit">Editar título</button>':''}${!e.voided&&ctx.can('finance','delete')?'<button class="danger" id="details-void">Cancelar título</button>':''}</div><h3>Baixas e estornos</h3>${payments.length?payments.map(s=>`<div class="history-row"><div><strong>${ctx.money(s.amount)} · ${ctx.date(s.paid_on)}</strong><p>${ctx.esc(b().accounts.find(a=>a.id===s.account_id)?.name||'Conta')} · ${ctx.esc(s.memo)}</p><span class="badge ${s.reversed?'danger-badge':s.statement_id?'success':''}">${s.reversed?'Estornado':s.statement_id?'Conciliado':'Registrado'}</span></div>${!s.reversed&&ctx.can('finance','reverse')?`<button class="secondary small" data-reverse="${s.id}">Estornar</button>`:''}</div>`).join(''):'<p class="muted">Nenhuma baixa registrada.</p>'}`,{wide:true});d.querySelector('#details-restore')?.addEventListener('click',async()=>{const reason=prompt('Motivo da reativação do título:');if(!reason)return;try{await ctx.rpc('restore_fin_entry',{p_id:id,p_reason:reason});await ctx.load();d.close();ctx.render('finance');ctx.toast('Título reativado com histórico preservado.')}catch(err){ctx.toast(err.message)}});d.querySelector('#details-settle')?.addEventListener('click',()=>{d.close();settlementDialog(id)});d.querySelector('#details-edit')?.addEventListener('click',()=>{d.close();entryDialog(e)});d.querySelector('#details-void')?.addEventListener('click',async()=>{const reason=prompt('Motivo do cancelamento do título:');if(!reason)return;try{await ctx.rpc('void_fin_entry',{p_id:id,p_reason:reason});await ctx.load();d.close();ctx.render('finance')}catch(err){ctx.toast(err.message)}});d.querySelectorAll('[data-reverse]').forEach(el=>el.onclick=async()=>{const reason=prompt('Motivo do estorno:');if(!reason)return;el.disabled=true;try{await ctx.rpc('reverse_settlement',{p_id:el.dataset.reverse,p_reason:reason});await ctx.load();d.close();entryDetails(id);ctx.toast('Baixa estornada. O histórico foi preservado.')}catch(err){ctx.toast(err.message);el.disabled=false}})}
 function receivableDialog(id){const q=ctx.quotes.find(q=>q.id===id);if(!q)return;const d=ctx.modal('Gerar parcelas do pedido #'+q.number,`<p class="muted">Entrada de ${q.entry_percentage}%: ${ctx.money(Number(q.total)*Number(q.entry_percentage)/100)}. Saldo: ${ctx.money(Number(q.total)*(1-Number(q.entry_percentage)/100))}.</p><form>${ctx.field('Vencimento da entrada','first','date',today(),'required')}${ctx.field('Vencimento do saldo','last','date',q.delivery_date||today(),'required')}<p class="note">As parcelas são geradas uma única vez por pedido. Repetir este comando não cria duplicatas.</p><p class="form-error" role="alert"></p><div class="form-actions"><button class="secondary" type="button" data-close>Cancelar</button><button class="primary" type="submit">Gerar contas a receber</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const v=new FormData(e.target);try{const n=await ctx.rpc('prepare_receivables',{p_quote:id,p_first_due:v.get('first'),p_final_due:v.get('last')});await ctx.load();d.close();ctx.toast(n?n+' parcela(s) criada(s).':'As parcelas deste pedido já estavam geradas.')}catch(err){d.querySelector('.form-error').textContent=err.message;e.submitter.disabled=false}}}
 function transferDialog(){if(b().accounts.filter(a=>a.active).length<2){ctx.toast('Cadastre ao menos duas contas ativas.');return}const request=crypto.randomUUID(),d=ctx.modal('Registrar transferência entre contas',`<form><label class="field">Conta de origem<select name="from">${accountsOptions()}</select></label><label class="field">Conta de destino<select name="to">${accountsOptions()}</select></label>${ctx.field('Valor (R$)','amount','number','','required min="0.01" step="0.01"')}${ctx.field('Data','date','date',today(),'required')}${ctx.field('Descrição','note','text','Transferência interna')}<p class="note">Registra as duas pontas de uma transferência já feita. Não é receita nem despesa operacional.</p><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button type="submit" class="primary">Registrar transferência</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const v=Object.fromEntries(new FormData(e.target));try{await ctx.rpc('transfer_accounts',{p_from:v.from,p_to:v.to,p_amount:Number(v.amount),p_date:v.date,p_note:v.note,p_request:request});await ctx.load();d.close();ctx.render('finance');ctx.toast('Transferência registrada nas duas contas.')}catch(err){d.querySelector('.form-error').textContent=err.message;e.submitter.disabled=false}}}
 function drawRecurring(){ctx.$('#finance-content').innerHTML=`<section class="panel"><div class="panelhead"><h2>Despesas fixas mensais</h2><button class="secondary small" id="generate-fixed" ${!ctx.can('finance','create')?'hidden':''}>Gerar competências</button></div>${b().recurring.length?`<div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Categoria</th><th>Valor mensal</th><th>Dia</th><th>Vigência</th><th></th></tr></thead><tbody>${b().recurring.map(r=>`<tr><td>${ctx.esc(r.description)}</td><td>${ctx.esc(r.category)}</td><td>${ctx.money(r.amount)}</td><td>${r.due_day}</td><td>${ctx.date(r.starts_on)}${r.ends_on?' até '+ctx.date(r.ends_on):''}</td><td><button class="secondary small" data-recurring="${r.id}" ${!ctx.can('finance','edit')?'disabled':''}>${r.active?'Pausar':'Reativar'}</button></td></tr>`).join('')}</tbody></table></div>`:ctx.empty('Configure suas despesas fixas.','Cadastre aluguel, energia e outros compromissos mensais.')}</section>`;ctx.$('#generate-fixed').onclick=generateRecurringDialog;document.querySelectorAll('[data-recurring]').forEach(el=>el.onclick=async()=>{const r=b().recurring.find(r=>r.id===el.dataset.recurring);try{await ctx.rpc('save_recurring',{p_id:r.id,p_data:{active:!r.active}});await ctx.load();financePage()}catch(err){ctx.toast(err.message)}})}
 function recurringDialog(){const d=ctx.modal('Nova despesa fixa mensal',`<form><div class="grid2">${ctx.field('Descrição','description','text','','required minlength="2"')}${categoryInput('Aluguel')}<label class="field">Classificação<select name="class">${['expense','cost','tax'].map(k=>`<option value="${k}">${CLASSES[k]}</option>`).join('')}</select></label>${ctx.field('Valor mensal (R$)','amount','number','','required min="0.01" step="0.01"')}${ctx.field('Dia do vencimento','due_day','number','10','required min="1" max="31"')}${ctx.field('Início da vigência','starts_on','date',today(),'required')}${ctx.field('Fim da vigência (opcional)','ends_on','date','')}</div><p class="note">Vencimentos em dias inexistentes no mês são ajustados para o último dia. Gerar o mesmo mês novamente não duplica a despesa.</p><p class="form-error" role="alert"></p><div class="form-actions"><button class="secondary" type="button" data-close>Cancelar</button><button class="primary">Salvar despesa fixa</button></div></form>`,{wide:true});d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const v=Object.fromEntries(new FormData(e.target));try{await ctx.rpc('save_recurring',{p_id:null,p_data:v});await ctx.load();d.close();selectedTab='recurring';financePage()}catch(err){d.querySelector('.form-error').textContent=err.message;e.submitter.disabled=false}}}
 function generateRecurringDialog(){const d=ctx.modal('Gerar contas das despesas fixas',`<form>${ctx.field('Primeira competência','month','month',today().slice(0,7),'required')}${ctx.field('Quantidade de meses','months','number','1','required min="1" max="12"')}<p class="form-error" role="alert"></p><div class="form-actions"><button class="secondary" type="button" data-close>Cancelar</button><button class="primary">Gerar lançamentos</button></div></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const v=new FormData(e.target);try{const n=await ctx.rpc('generate_recurring',{p_month:v.get('month')+'-01',p_months:Number(v.get('months'))});await ctx.load();d.close();financePage();ctx.toast(n+' lançamento(s) criado(s); competências já existentes foram preservadas.')}catch(err){d.querySelector('.form-error').textContent=err.message;e.submitter.disabled=false}}}
 async function drawAudit(){ctx.$('#finance-content').innerHTML='<section class="panel"><p class="loading">Consultando histórico…</p></section>';try{const rows=await ctx.api('/rest/v1/fin_audit?select=*&order=created_at.desc&limit=100');const labels={final_receipt_issued:'Recibo final emitido',receipt_issued:'Recibo emitido',entry_saved:'Lançamento salvo',settled:'Baixa registrada',reversed:'Baixa estornada',entry_voided:'Título cancelado',bank_imported:'Extrato importado',bank_reconciled:'Movimentação conciliada',bank_ignored:'Linha ignorada',bank_restored:'Conferência reaberta',entry_restored:'Título reativado',transfer_reversed:'Transferência estornada',account_saved:'Conta configurada',receivables_prepared:'Parcelas do pedido geradas'};ctx.$('#finance-content').innerHTML=`<section class="panel"><div class="panelhead"><h2>Últimas 100 operações</h2></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Data e hora</th><th>Operação</th><th>Referência</th><th>Detalhe</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${new Date(r.created_at).toLocaleString('pt-BR')}</td><td>${ctx.esc(labels[r.action]||r.action)}</td><td>${ctx.esc(r.object_id?.slice(0,8))}</td><td>${ctx.esc(r.detail.reason||r.detail.name||(r.detail.amount?ctx.money(r.detail.amount):r.detail.rows!==undefined?r.detail.rows+' linhas':''))}</td></tr>`).join('')}</tbody></table></div>`:ctx.empty('Nenhuma operação registrada.','O histórico é criado pelas operações do sistema.')}</section>`}catch(e){ctx.$('#finance-content').textContent=e.message}}
 Object.assign(ctx,{financePage,entryDialog,entryDetails,settlementDialog,receivableDialog,accountsOptions,groupOptions,categoryInput});
}
